// glass.conf parsing, kept free of Hyprland so it can be tested alone
// (`make test`).
#pragma once

#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <map>
#include <optional>
#include <sstream>
#include <string>

#include "glass_def.hpp"

// glass.conf is generated by the shell from glass.def; parse it strictly
// against the same definition (GLASS_FIELDS): every key exactly once, known,
// well-formed and in range. Anything else rejects the whole file.
using Values                                = std::map<std::string, float>;
static constexpr std::size_t MAX_CONF_BYTES = 16 * 1024;

static std::string           trimmed(const std::string& s) {
    const auto a = s.find_first_not_of(" \t\r");
    const auto b = s.find_last_not_of(" \t\r");
    return a == std::string::npos ? "" : s.substr(a, b - a + 1);
}

static const SGlassField* fieldFor(const std::string& key) {
    for (const auto& f : GLASS_FIELDS)
        if (key == f.key)
            return &f;
    return nullptr;
}

static std::optional<Values> parseConf(const std::string& text, std::string& error) {
    Values             values;
    std::istringstream in(text);
    int                n = 0;
    for (std::string raw; std::getline(in, raw);) {
        ++n;
        const std::string line = trimmed(raw);
        if (line.empty() || line[0] == '#')
            continue;
        const auto at = "line " + std::to_string(n) + ": ";
        const auto eq = line.find('=');
        if (eq == std::string::npos) {
            error = at + "expected key=value";
            return std::nullopt;
        }
        const std::string key = trimmed(line.substr(0, eq)), text = trimmed(line.substr(eq + 1));
        const auto*       f = fieldFor(key);
        if (!f) {
            error = at + "unknown key \"" + key + "\"";
            return std::nullopt;
        }
        if (values.contains(key)) {
            error = at + key + " given twice";
            return std::nullopt;
        }
        float v = 0;
        if (f->flag) {
            if (text != "0" && text != "1") {
                error = at + key + " must be 0 or 1";
                return std::nullopt;
            }
            v = text == "1" ? 1.f : 0.f;
        } else {
            char* end = nullptr;
            errno     = 0;
            v         = std::strtof(text.c_str(), &end);
            if (text.empty() || end != text.c_str() + text.size() || errno == ERANGE || !std::isfinite(v)) {
                error = at + key + " isn't a number";
                return std::nullopt;
            }
            if (v < f->min || v > f->max) {
                error = at + key + " is out of range";
                return std::nullopt;
            }
        }
        values[key] = v;
    }
    for (const auto& f : GLASS_FIELDS) {
        if (!values.contains(f.key)) {
            error = std::string("missing ") + f.key;
            return std::nullopt;
        }
    }
    return values;
}

static Values defaultValues() {
    Values v;
    for (const auto& f : GLASS_FIELDS)
        v[f.key] = f.def;
    return v;
}
